const rawInput = $input.first().json;
const body = rawInput.body ? rawInput.body : rawInput;

if (!body.sku || !body.marketplace_id) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'MISSING_REQUIRED_FIELDS',
    message: 'sku and marketplace_id are both required. Note: this endpoint is SKU-keyed (the seller\'s own internal SKU), not ASIN-keyed - use wf17 for ASIN/Catalog lookups.'
  }}];
}

// seller_id will become a real request field in Day 26's multi-seller work.
// Hardcoded here deliberately, consistent with wf15/17/18 - not new debt,
// same debt, tracked in one place.
return [{ json: {
  decision: 'VALID',
  seller_id: '4b88cbec-c02f-4416-8f22-4a7b35316b60',
  sku: String(body.sku).trim(),
  marketplace_id: body.marketplace_id,
  asin_hint: body.asin || null
}}];

const rows = $input.first().json;
const ctx = $('Validate Input').first().json;
const row = Array.isArray(rows) ? rows[0] : rows;

if (!row || !row.selling_partner_id) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'SELLING_PARTNER_ID_NOT_FOUND',
    seller_id: ctx.seller_id,
    message: 'No Amazon Selling Partner ID is stored for this seller yet. Complete the self-authorization step and store the Merchant Token before calling this endpoint (see Day 24 prerequisite).'
  }}];
}

return [{ json: {
  decision: 'HAS_IDENTITY',
  seller_id: ctx.seller_id,
  selling_partner_id: row.selling_partner_id,
  sku: ctx.sku,
  marketplace_id: ctx.marketplace_id,
  asin_hint: ctx.asin_hint
}}];

const identity = $('Identity Gate').first().json;
const token = $input.first().json.access_token;

const included = 'summaries,attributes,issues';
const url = 'https://sellingpartnerapi-na.amazon.com/listings/2021-08-01/items/'
  + encodeURIComponent(identity.selling_partner_id) + '/'
  + encodeURIComponent(identity.sku)
  + '?marketplaceIds=' + encodeURIComponent(identity.marketplace_id)
  + '&includedData=' + encodeURIComponent(included);

return [{ json: { url: url, access_token: token } }];

const upstream = $input.first().json;
const identity = $('Identity Gate').first().json;

// A genuine SP-API 404 for an unlisted SKU, or any other upstream error.
if (!upstream || upstream.error || (!upstream.sku && !upstream.summaries)) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'LISTING_NOT_FOUND',
    sku: identity.sku,
    marketplace_id: identity.marketplace_id,
    message: 'No listing was found for this SKU under this seller account in this marketplace. Check the SKU and marketplace_id.',
    upstream_raw: upstream
  }}];
}

function forMarketplace(list) {
  if (!Array.isArray(list)) return {};
  return list.find(function(e) { return e.marketplaceId === identity.marketplace_id; }) || list[0] || {};
}

const summary = forMarketplace(upstream.summaries);

// DEFENSIVE PARSE (Day 24, first-ever call to this endpoint in the rebuild):
// written against the documented Listings Items attribute shape, same
// pattern as wf17's first build - if real data comes back differently,
// paste the raw response and the parse gets corrected against real shape,
// same as every other endpoint in this project so far.
const rawAttributes = upstream.attributes || {};
const attributes = {};
Object.keys(rawAttributes).forEach(function(attrName) {
  const entries = rawAttributes[attrName];
  if (!Array.isArray(entries) || entries.length === 0) {
    attributes[attrName] = entries;
    return;
  }
  const relevant = entries.filter(function(e) { return !e.marketplace_id || e.marketplace_id === identity.marketplace_id; });
  const list = relevant.length > 0 ? relevant : entries;
  const allHaveValue = list.every(function(e) { return e && e.value !== undefined; });

  if (allHaveValue && list.length === 1) {
    attributes[attrName] = list[0].value;                            // color, brand, list_price, ... (proven: "Blue")
  } else if (allHaveValue) {
    attributes[attrName] = list.map(function(e) { return e.value; }); // bullet_point -> all 5 values now, not just #1
  } else {
    attributes[attrName] = entries;                                   // shirt_size, neck, sleeve, images: compound, kept raw
  }
});

const issues = Array.isArray(upstream.issues) ? upstream.issues : [];

return [{ json: {
  decision: 'LISTING_FOUND',
  sku: identity.sku,
  asin_hint: identity.asin_hint,
  marketplace_id: identity.marketplace_id,
  product_type: summary.productType || null,
  status: summary.status || null,
  item_name: summary.itemName || null,
  attributes: attributes,
  attribute_names_set: Object.keys(attributes),
  issues: issues,
  has_issues: issues.length > 0,
  raw_upstream: upstream
}}];
